        if ((upright == 1) && (sz0 > 0)) {
            int sz = Lists.LsCap(Evidence.GlGet(gl, g, Evidence.GfSize()));
            int by = Lists.LsCap(Evidence.GlGet(gl, g, Evidence.GfBy0()));
            if ((sz * 100) <= (sz0 * 88)) {
                if (((Lists.LsCap(@base) - by) * 100) >= (sz0 * 12)) {
                    bits |= 32;
                }
                if (((by - Lists.LsCap(@base)) * 100) >= (sz0 * 12)) {
                    bits |= 16;
                }
            }
        }
        return bits;
    }
    internal static int IlLinkOf(emon.Port.Cells sw, int ncand, int lo, int hi, emon.Port.Cells text, emon.Port.Cells txt, int cx, int cy) {
        // The link number plus one of the link at the point, 0 when there is none.
        if (lo >= hi) {
            return 0;
        }
        int j = IlHit(sw, lo, hi, cx, cy);
        if (j < 0) {
            return 0;
        }
        return IlUse(sw, ncand, text, txt, j) + 1;
    }
    internal static int IlGrouped(emon.Port.Cells wd, emon.Port.Cells et, int w) {
        // 1 when the word's text holds a group of the list or note stage (U+FDD0..U+FDEF): it is not its glyphs.
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        int i = 0;
        while (i < tl) {
            int c = emon.Port.CellsAt(et, ts + i);
            if ((c >= 64976) && (c <= 65007)) {
                return 1;
            }
            i += 1;
        }
        return 0;
    }
    internal static int IlWord(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells ift, emon.Port.Cells sw, int ncand, int lo, int hi, emon.Port.Cells text, emon.Port.Cells txt, emon.Port.Cells hc, int b, int w, int sz0, int @base, int upright) {
        // Write word w's states at the end of the data and its word table entry (see the head). Answers 1 when any
        // character of it has a state.
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        int gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
        int g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
        int d0 = emon.Port.CellsLen(hc);
        int te = emon.Port.CellsAt(hc, b + 4) + (w * 2);
        int eq = 0;
        int nz = 0;
        int same = 1;
        int first = 0;
        int st = 0;
        int j = 0;
        int g = 0;
        if ((ts < 0) || (tl <= 0)) {
            return 0;
        }
        if ((tl == gn) && (gn > 0) && (gn <= IlMaxg) && (g0 >= 0) && (IlGrouped(wd, et, w) == 0)) {
            eq = 1;
        }
        if (eq == 1) {
            while (j < tl) {
                g = g0 + j;
                st = IlGlyphBits(gl, ift, g, sz0, @base, upright);
                st += 256 * IlLinkOf(sw, ncand, lo, hi, text, txt, (Evidence.GlGet(gl, g, Evidence.HdX0()) + Evidence.GlGet(gl, g, Evidence.HdX1())) / 2, (Evidence.GlGet(gl, g, Evidence.HdY0()) + Evidence.GlGet(gl, g, Evidence.HdY1())) / 2);
                emon.Port.CellsPush(hc, st);
                if (st != 0) {
                    nz = 1;
                }
                if (j == 0) {
                    first = st;
                }
                if (st != first) {
                    same = 0;
                }
                j += 1;
            }
        } else {
            int fi = Evidence.WdGet(wd, w, Evidence.WfFont());
            if ((fi >= 0) && (fi < emon.Port.CellsLen(ift))) {
                st = emon.Port.CellsAt(ift, fi);
            }
            st += 256 * IlLinkOf(sw, ncand, lo, hi, text, txt, (Evidence.WdGet(wd, w, Evidence.HdX0()) + Evidence.WdGet(wd, w, Evidence.HdX1())) / 2, (Evidence.WdGet(wd, w, Evidence.HdY0()) + Evidence.WdGet(wd, w, Evidence.HdY1())) / 2);
            emon.Port.CellsPush(hc, st);
            if (st != 0) {
                nz = 1;
            }
        }
        if (nz == 0) {
            emon.Port.CellsDrop(hc, d0);
            return 0;
        }
        if (same == 1) {
            emon.Port.CellsDrop(hc, d0 + 1);
        }
        emon.Port.CellsSet(hc, te, d0 - emon.Port.CellsAt(hc, b + 5));
        emon.Port.CellsSet(hc, te + 1, emon.Port.CellsLen(hc) - d0);
        return 1;
    }
    public static int IlAnalyze(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells ift, emon.Port.Cells sf, emon.Port.Cells an, emon.Port.Cells txt, emon.Port.Cells pg, emon.Port.Cells pages, int npages, emon.Port.Cells text, emon.Port.Cells hc, emon.Port.Cells sw) {
        // Find the style and the link of every character of every word and write them after the lists' rows in `hc`
        // (see the head). `sw` is scratch. Answers 1 when the block was written, 0 when no character has a state (and `hc`
        // is as it was).
        int e = Heading.HdRowsEnd(hc);
        int nw = Evidence.WdCount(wd);
        int nl = Evidence.LnCount(ln);
        int b = -1;
        int ncand = 0;
        int l = 0;
        int k = 0;
        int any = 0;
        int cp = -1;
        int lo = 0;
        int hi = 0;
        int sz0 = 0;
        int @base = 0;
        int up = 0;
        int w0 = 0;
        int wn = 0;
        int rot = 0;
        int nlk = 0;
        int i = 0;
        if (e < 0) {
            return 0;
        }
        b = e + (emon.Port.CellsAt(hc, 0) * IlLs);
        if (emon.Port.CellsLen(hc) != b) {
            return 0;
        }
        if ((nw == 0) || (nl == 0)) {
            return 0;
        }
        ncand = IlCands(an, txt, pg, pages, npages, sw);
        emon.Port.CellsPush(hc, IlMagic);
        emon.Port.CellsPush(hc, nw);
        emon.Port.CellsPush(hc, 0);
        emon.Port.CellsPush(hc, 0);
        emon.Port.CellsPush(hc, b + IlHdr);
        emon.Port.CellsPush(hc, (b + IlHdr) + (nw * 2));
        emon.Port.CellsPush(hc, 0);
        emon.Port.CellsPush(hc, 0);
        while (i < nw) {
            emon.Port.CellsPush(hc, -1);
            emon.Port.CellsPush(hc, 0);
            i += 1;
        }
        while (l < nl) {
            int pgn = Evidence.LnGet(ln, l, Evidence.LhPage());
            if (pgn != cp) {
                cp = pgn;
                lo = 0;
                while ((lo < ncand) && (emon.Port.CellsAt(sw, lo * IlCand) < pgn)) {
                    lo += 1;
                }
                hi = lo;
                while ((hi < ncand) && (emon.Port.CellsAt(sw, hi * IlCand) == pgn)) {
                    hi += 1;
                }
            }
            rot = Evidence.LnGet(ln, l, Evidence.LhRot());
            up = 0;
            if ((rot < 100) || (rot > 35900)) {
                up = 1;
            }
            sz0 = Lists.LsLineSize(sf, ln, l);
            @base = Evidence.LnGet(ln, l, Evidence.LhBy0());
            w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
            wn = Evidence.LnGet(ln, l, Evidence.LhCount());
            k = 0;
            while (k < wn) {
                if (((w0 + k) >= 0) && ((w0 + k) < nw)) {
                    if (IlWord(wd, et, gl, ift, sw, ncand, lo, hi, text, txt, hc, b, w0 + k, sz0, @base, up) == 1) {
                        any = 1;
                    }
                }
                k += 1;
            }
            l += 1;
        }
        if (any == 0) {
            emon.Port.CellsDrop(hc, b);
            return 0;
        }
        nlk = (emon.Port.CellsLen(sw) - (ncand * IlCand)) / IlLk;
        emon.Port.CellsSet(hc, b + 6, emon.Port.CellsLen(hc));
        emon.Port.CellsSet(hc, b + 3, nlk);
        i = ncand * IlCand;
        while (i < emon.Port.CellsLen(sw)) {
            emon.Port.CellsPush(hc, emon.Port.CellsAt(sw, i));
            i += 1;
        }
        return 1;
    }
    public static int IlMark(emon.Port.Cells raw, int v) {
        // Push the marker for state v: the opener, the number's digits, the end of a group.
        int d = 1;
        int x = 0;
        emon.Port.CellsPush(raw, IlSSty());
        while ((d * 10) <= v) {
            d *= 10;
        }
        x = v;
        while (d > 0) {
            emon.Port.CellsPush(raw, 48 + (x / d));
            x = x % d;
            d = d / 10;
        }
        emon.Port.CellsPush(raw, Lists.LsSEnd());
        return 0;
    }
    public static int IlMarkEnd(emon.Port.Cells raw, int s, int n) {
        // One past the end of the marker that opens at s, -1 when it is not closed before n.
        int i = s + 1;
        while (i < n) {
            if (emon.Port.CellsAt(raw, i) == Lists.LsSEnd()) {
                return i + 1;
            }
            i += 1;
        }
        return -1;
    }
    public static int IlMarkValue(emon.Port.Cells raw, int s, int gend) {
        // The state of the marker raw[s, gend).
        int i = s + 1;
        int v = 0;
        while (i < (gend - 1)) {
            v = (v * 10) + (emon.Port.CellsAt(raw, i) - 48);
            i += 1;
        }
        return v;
    }
    public static int IlBits(int st) {
        return st % 256;
    }
    public static int IlLink(int st) {
        // The link number plus one of a state, 0 for none.
        return st / 256;
    }
    public static int IlMix(int a, int b) {
        // What two neighbours share: the bits they have both, the link when it is the same. The space between two
        // words has this state.
        int v = IlBits(a) & IlBits(b);
        if (IlLink(a) == IlLink(b)) {
            v += 256 * IlLink(a);
        }
        return v;
    }
    public static int IlEff(int st, int @base) {
        // The state as it is written, against the style the paragraph is set in (bold, italic and monospace that most of
        // its characters have are not marked).
        int bits = IlBits(st);
        return (bits - (bits & (@base & IlStyle))) + (256 * IlLink(st));
    }
    public static int IlStateAt(emon.Port.Cells raw, int upto) {
        // The state the text is in at raw[upto]: the last marker before it.
        int i = 0;
        int v = 0;
        while (i < upto) {
            if (emon.Port.CellsAt(raw, i) == IlSSty()) {
                int ge = IlMarkEnd(raw, i, upto);
                if (ge > 0) {
                    v = IlMarkValue(raw, i, ge);
                    i = ge - 1;
                }
            }
            i += 1;
        }
        return v;
    }
    public static int IlHas(emon.Port.Cells raw, int n) {
        // 1 when raw[0, n) has a marker.
        int i = 0;
        while (i < n) {
            if (emon.Port.CellsAt(raw, i) == IlSSty()) {
                return 1;
            }
            i += 1;
        }
        return 0;
    }
    public static int IlBaseOf(emon.Port.Cells raw, int n) {
        // The style bits most of the characters of raw[0, n) have: bold, italic, monospace each when more than half of
        // the characters that are not spaces are in it. A group of another stage is not a character.
        int i = 0;
        int v = 0;
        int total = 0;
        int nb = 0;
        int ni = 0;
        int nm = 0;
        int nc = 0;
        int c = 0;
        int ge = 0;
        int res = 0;
        while (i < n) {
            c = emon.Port.CellsAt(raw, i);
            if (c == IlSSty()) {
                ge = IlMarkEnd(raw, i, n);
                if (ge > 0) {
                    v = IlMarkValue(raw, i, ge);
                    i = ge;
                } else {
                    i += 1;
                }
            } else if ((c == Lists.LsSItem()) || ((c == Lists.LsSNote()) || ((c == Lists.LsSCap()) || (c == Lists.LsSRef())))) {
                ge = IlMarkEnd(raw, i, n);
                if (ge > 0) {
                    i = ge;
                } else {
                    i += 1;
                }
            } else {
                if (c != 32) {
                    total += 1;
                    if ((IlBits(v) & 1) != 0) {
                        nb += 1;
                    }
                    if ((IlBits(v) & 2) != 0) {
                        ni += 1;
                    }
                    if ((IlBits(v) & 64) != 0) {
                        nm += 1;
                    }
                    if ((IlBits(v) & 128) != 0) {
                        nc += 1;
                    }
                }
                i += 1;
            }
        }
        if ((nb * 2) > total) {
            res += 1;
        }
        if ((ni * 2) > total) {
            res += 2;
        }
        if ((nm * 2) > total) {
            res += 64;
        }
        if ((nc * 2) > total) {
            res += 128;
        }
        return res;
    }
    public static int IlStyled(emon.Port.Cells raw, int n, int @base) {
        // 1 when some marker in raw[0, n) is a state that is written (`il-eff` not zero).
        int i = 0;
        int ge = 0;
        while (i < n) {
            if (emon.Port.CellsAt(raw, i) == IlSSty()) {
                ge = IlMarkEnd(raw, i, n);
                if (ge > 0) {
                    if (IlEff(IlMarkValue(raw, i, ge), @base) != 0) {
                        return 1;
                    }
                    i = ge - 1;
                }
            }
            i += 1;
        }
        return 0;
    }
}
